struct Tampon {
    char* d;
    ~Tampon() { delete[] d; }
};
Tampon a{new char[10]};
Tampon b = a; // b.d == a.d
// fin de portée : double delete[] !

Tampon(const Tampon& o)
    : d(new char[o.n]), n(o.n) {
    std::copy(o.d, o.d + n, d);
}

Tampon& operator=(Tampon o) { // copie
    std::swap(d, o.d);
    std::swap(n, o.n);
    return *this;
} // o (l'ancien contenu) est détruit

